const _templateCache = new Map<string, RegExp>()

/** Convierte `/a/{id}/b` en una regex que matchea un path concreto. */
function _template(path: string): RegExp {
  const hit = _templateCache.get(path)
  if (hit) return hit
  const src =
    '^' +
    path
      .split('/')
      .map((seg) => (/^\{[^}]+\}$/.test(seg) ? '[^/]+' : seg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')))
      .join('/') +
    '$'
  const re = new RegExp(src)
  _templateCache.set(path, re)
  return re
}

/**
 * Busca la ruta declarada que corresponde a (método, path concreto).
 * Devuelve undefined si el backend no expone esa ruta: sirve para fallar
 * temprano en tests en vez de recibir un 404 en runtime.
 */
export function findApiRoute(method: string, path: string): ApiRoute | undefined {
  const sinQuery = path.split('?')[0]
  const m = method.toUpperCase()
  return API_ROUTES.find((r) => r.method === m && _template(r.path).test(sinQuery))
}
